-- Comprobación informativa: cada tipo debe mostrar 3 evidencias.
SELECT t.nombre_tipo, COUNT(e.id_evidencia) AS evidencias_demo
FROM tipos_de_evidencia t
JOIN evidencias e ON e.id_tipo_evidencia = t.id_tipo_evidencia
WHERE LEFT(t.nombre_tipo, 7) = '[DEMO] '
GROUP BY t.id_tipo_evidencia, t.nombre_tipo
ORDER BY t.id_tipo_evidencia;
